import { test, expect } from '@playwright/test';

test.describe('Right-click Row Context Menu', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should display context menu with correct options when right-clicking a row', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Get first row using getByRole
    const firstRow = page.getByRole('row', { name: /row 1/i });
    await expect(firstRow).toBeVisible();

    // Right-click the first row
    await firstRow.rightClick();

    // Wait for context menu to appear
    const contextMenu = page.locator('[data-testid="context-menu"]');
    await page.waitForTimeout(100);

    // Verify context menu is visible
    await expect(contextMenu).toBeVisible();

    // Verify context menu contains expected options
    const copyAction = page.getByRole('button', { name: /copy/i });
    await expect(copyAction).toBeVisible();

    const editAction = page.getByRole('button', { name: /edit/i });
    await expect(editAction).toBeVisible();

    const deleteAction = page.getByRole('button', { name: /delete/i });
    await expect(deleteAction).toBeVisible();

    // Verify context menu is positioned correctly
    const contextMenuPosition = page.evaluate(() => {
      const menu = document.querySelector('[data-testid="context-menu"]');
      return {
        x: window.getComputedStyle(menu).getPropertyValue('left'),
        y: window.getComputedStyle(menu).getPropertyValue('top')
      };
    });

    expect(contextMenuPosition.x).toBeGreaterThan(0);
    expect(contextMenuPosition.y).toBeGreaterThan(0);

    // Verify context menu is not visible when clicking outside
    const outsideElement = page.locator('body');
    await outsideElement.click();
    await expect(contextMenu).not.toBeVisible();
  });

  test('should not display context menu when clicking outside of table', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Get first row using getByRole
    const firstRow = page.getByRole('row', { name: /row 1/i });
    await expect(firstRow).toBeVisible();

    // Right-click the first row
    await firstRow.rightClick();

    // Verify context menu appears
    const contextMenu = page.locator('[data-testid="context-menu"]');
    await expect(contextMenu).toBeVisible();

    // Click outside of table
    const outsideElement = page.locator('body');
    await outsideElement.click();

    // Verify context menu is not visible
    await expect(contextMenu).not.toBeVisible();
  });
});
